def spiral_order(matrix: list[list[int]]) -> list[int]:
    result = []
    while matrix:
        result.extend(matrix.pop(0))
        if matrix:
            for row in matrix:
                result.append(row.pop())
        if matrix:
            result.extend(matrix.pop()[::-1])
        if matrix:
            for row in matrix[::-1]:
                result.append(row.pop(0))
    return result
