def word_break(s: str, word_dict: list[str]) -> bool:
    dp = [False] * (len(s) + 1)
    dp[0] = True

    for i in range(1, len(s) + 1):
        for word in word_dict:
            if i >= len(word) and s[i - len(word):i] == word:
                dp[i] = dp[i] or dp[i - len(word)]

    return dp[-1]
```

